\\n            self._set_status(\\"Unsaved Task Templates draft kept; source refresh skipped.\\")\\n            return\\n        before = self.digest(path)\\n        with path.open(encoding=\\"utf-8-sig\\", newline=\\"\\") as handle:\\n            rows = [dict(row) for row in csv.DictReader(handle) if any(row.values())]\\n        if before != self.digest(path):\\n            raise ValueError(\\"Task CSV changed during refresh. Refresh again.\\")\\n        choices = {field: self.choices(field) for field in (\\n            \\"capability_id\\", \\"priority\\", \\"target_type\\", \\"target_family_id\\", \\"reward_mode\\"\\n        )}\\n        for field, values in choices.items():\\n            self.widgets[field].configure(values=values)\\n        self.loaded_rows = rows\\n        self.snapshot_hash = before\\n        self.loaded_path = path.resolve()\\n        self.dirty = False\\n        self._render_draft()\\n        if self.editing_id and self.tree.exists(self.editing_id):\\n            self.tree.selection_set(self.editing_id)\\n            self.on_select()\\n        else:\\n            self.new()\\n        self._set_status(f\\"{len(rows)} templates loaded from source.\\")\\n"], ["doda_task_templates_editor.py", "    def save(self):\\n        if not require_single(self, \\"Save Template\\", messagebox):\\n            return\\n        try:\\n            row = self.record()\\n            key = row[\\"task_template_id\\"]\\n            if self.editing_id and key != self.editing_id:\\n                raise ValueError(\\"Template ID cannot change after creation.\\")\\n            if not self.editing_id and any(\\n                r[\\"task_template_id\\"] == key for r in self.loaded_rows\\n            ):\\n                raise ValueError(\\"Template ID already exists.\\")\\n            rows = [\\n                dict(r) for r in self.loaded_rows\\n                if r[\\"task_template_id\\"] != key\\n            ] + [row]\\n            self.commit(rows)\\n            self.editing_id = key\\n            self.tree.selection_set(key)\\n            self.on_select()\\n        except (OSError, ValueError) as error:\\n            messagebox.showerror(\\"Task Templates\\", str(error), parent=self.app)\\n", "    def save(self):\\n        if not self.dirty:\\n            self._set_status(\\"No applied draft changes to save. Use Apply to List first.\\")\\n            return\\n        try:\\n            self.commit(self.loaded_rows)\\n        except (OSError, UnicodeError, csv.Error, ValueError) as error:\\n            self.app.log(f\\"Task Templates save blocked; draft retained: {error}\\")\\n            self._set_status(\\"Save blocked; draft retained. See Activity Log.\\")\\n            messagebox.showerror(\\"Task Templates\\", str(error), parent=self.app)\\n"], ["doda_task_templates_editor.py", "    def commit(self, rows):\\n        path = self.source_path()\\n        if self.snapshot_hash is None or self.digest(path) != self.snapshot_hash:\\n            raise ValueError(\\"Task CSV changed externally. Refresh before saving.\\")\\n        temporary = path.with_name(f\\".tasks-{uuid4().hex}.tmp.csv\\")\\n        try:\\n            with temporary.open(\\"w\\", encoding=\\"utf-8\\", newline=\\"\\") as handle:\\n                writer = csv.DictWriter(\\n                    handle, fieldnames=FIELDS, lineterminator=\\"\\\\n\\"\\n                )\\n                writer.writeheader()\\n                writer.writerows(sorted(rows, key=lambda row: (\\n                    int(row[\\"sort_order\\"]), row[\\"task_template_id\\"]\\n                )))\\n            valid, output = self.candidate_valid(temporary)\\n            self.app.log(output)\\n            if not valid:\\n                raise ValueError(\\"Candidate validation failed. CSV unchanged; see Activity Log.\\")\\n            if self.digest(path) != self.snapshot_hash:\\n                raise ValueError(\\"Task CSV changed during validation. CSV unchanged.\\")\\n            folder = self.backup_directory()\\n            folder.mkdir(parents=True, exist_ok=True)\\n            backup = folder / (\\n                \\"task_templates_\\" + datetime.now().strftime(\\"%Y%m%d_%H%M%S_%f\\")\\n                + \\".csv\\"\\n            )\\n            shutil.copy2(path, backup)\\n            os.replace(temporary, path)\\n            self.app.log(f\\"Task Templates saved. Backup: {backup}\\")\\n            self.app.refresh_all(False)\\n            messagebox.showinfo(\\n                \\"Task Templates\\", f\\"Candidate validation passed.\\\\nBackup: {backup}\\",\\n                parent=self.app\\n            )\\n        finally:\\n            if temporary.exists():\\n                temporary.unlink()\\n", "    def commit(self, rows):\\n        path = self.source_path()\\n        if self.loaded_path is not None and path.resolve() != self.loaded_path:\\n            raise ValueError(\\"Task Templates project changed. Draft retained; save blocked.\\")\\n        if self.snapshot_hash is None or self.digest(path) != self.snapshot_hash:\\n            raise ValueError(\\"Task CSV changed externally. Draft retained. Revert Draft to reload before reapplying edits.\\")\\n        temporary = path.with_name(f\\".tasks-{uuid4().hex}.tmp.csv\\")\\n        try:\\n            with temporary.open(\\"w\\", encoding=\\"utf-8\\", newline=\\"\\") as handle:\\n                writer = csv.DictWriter(handle, fieldnames=FIELDS, lineterminator=\\"\\\\n\\")\\n                writer.writeheader()\\n                writer.writerows(sorted(rows, key=lambda row: (int(row[\\"sort_order\\"]), row[\\"task_template_id\\"])))\\n            valid, output = self.candidate_valid(temporary)\\n            self.app.log(output)\\n            if not valid:\\n                raise ValueError(\\"Candidate validation failed. Draft retained; CSV unchanged. See Activity Log.\\")\\n            if self.digest(path) != self.snapshot_hash:\\n                raise ValueError(\\"Task CSV changed during validation. Draft retained; CSV unchanged.\\")\\n            folder = self.backup_directory()\\n            folder.mkdir(parents=True, exist_ok=True)\\n            backup = folder / (\\"task_templates_\\" + datetime.now().strftime(\\"%Y%m%d_%H%M%S_%f\\") + \\".csv\\")\\n            shutil.copy2(path, backup)\\n            if self.digest(path) != self.snapshot_hash:\\n                raise ValueError(\\"Task CSV changed while preparing the backup. Draft retained; save blocked.\\")\\n            os.replace(temporary, path)\\n        finally:\\n            try:\\n                temporary.unlink(missing_ok=True)\\n            except OSError as error:\\n                self.app.log(f\\"Task Templates temporary-file cleanup warning: {error}\\")\\n        self.snapshot_hash = self.digest(path)\\n        self.loaded_path = path.resolve()\\n        self.dirty = False\\n        self.app.log(f\\"Task Templates saved. Backup: {backup}\\")\\n        self._set_status(\\"Task Templates saved to source.\\")\\n        self.app.refresh_all(False)\\n        messagebox.showinfo(\\"Task Templates\\", f\\"Candidate validation passed.\\\\nBackup: {backup}\\", parent=self.app)\\n"], ["doda_task_templates_editor.py", "    def remove(self):\\n        if not require_single(self, \\"Remove Template\\", messagebox):\\n            return\\n        if not self.editing_id:\\n            messagebox.showwarning(\\n                \\"Task Templates\\", \\"Select a template first.\\", parent=self.app\\n            )\\n            return\\n        key = self.editing_id\\n        if not messagebox.askyesno(\\n            \\"Remove Template?\\", f\\"Remove \'{key}\'?\\\\nA CSV backup will be created.\\",\\n            default=messagebox.NO, icon=\\"warning\\", parent=self.app\\n        ):\\n            return\\n        try:\\n            self.commit([\\n                dict(row) for row in self.loaded_rows\\n                if row[\\"task_template_id\\"] != key\\n            ])\\n            self.new()\\n        except (OSError, ValueError) as error:\\n            messagebox.showerror(\\"Task Templates\\", str(error), parent=self.app)\\n", "    def remove(self):\\n        if not require_single(self, \\"Delete from List\\", messagebox):\\n            return\\n        if not self.editing_id:\\n            messagebox.showwarning(\\"Task Templates\\", \\"Select a template first.\\", parent=self.app)\\n            return\\n        key = self.editing_id\\n        if not messagebox.askyesno(\\"Delete from Draft?\\", f\\"Remove \'{key}\' from the draft?\\\\nSource changes only after Save to Source.\\",\\n                                 default=messagebox.NO, icon=\\"warning\\", parent=self.app):\\n            return\\n        candidate = [dict(row) for row in self.loaded_rows if row[\\"task_template_id\\"] != key]\\n        if len(candidate) == len(self.loaded_rows):\\n            self._set_status(\\"Selected template is no longer present in the draft.\\")\\n            return\\n        try:\\n            self._validate_rows(candidate)\\n        except (OSError, UnicodeError, csv.Error, ValueError) as error:\\n            self.app.log(f\\"Task Templates delete blocked; draft retained: {error}\\")\\n            messagebox.showerror(\\"Task Templates\\", str(error), parent=self.app)\\n            return\\n        self.loaded_rows = candidate\\n        self.dirty = True\\n        self.editing_id = None\\n        self._render_draft()\\n        self.new()\\n        self._set_status(\\"Template removed from draft. UNSAVED CHANGES.\\")\\n"], ["doda_task_templates_editor.py", "    def open_backups(self):", "    def _set_status(self, text):\\n        self.status.set(text)\\n\\n    def _render_draft(self):\\n        for item in self.tree.get_children():\\n            self.tree.delete(item)\\n        for row in sorted(self.loaded_rows, key=lambda r: (int(r[\\"sort_order\\"]), r[\\"task_template_id\\"])):\\n            self.tree.insert(\\"\\", \\"end\\", iid=row[\\"task_template_id\\"], values=tuple(row[field] for field in self.tree[\\"columns\\"]))\\n\\n    def _validate_rows(self, rows):\\n        with tempfile.TemporaryDirectory(prefix=\\"doda-task-draft-\\") as folder:\\n            candidate = Path(folder) / \\"task_templates.csv\\"\\n            with candidate.open(\\"w\\", encoding=\\"utf-8\\", newline=\\"\\") as handle:\\n                writer = csv.DictWriter(handle, fieldnames=FIELDS, lineterminator=\\"\\\\n\\")\\n                writer.writeheader()\\n                writer.writerows(rows)\\n            valid, output = self.candidate_valid(candidate)\\n        self.app.log(output)\\n        if not valid:\\n            raise ValueError(\\"Draft candidate validation failed; no draft rows changed. See Activity Log.\\")\\n\\n    def apply_record(self):\\n        if not require_single(self, \\"Apply to List\\", messagebox):\\n            return\\n        try:\\n            row = self.record()\\n            key = row[\\"task_template_id\\"]\\n            if self.editing_id and key != self.editing_id:\\n                raise ValueError(\\"Template ID cannot change after creation.\\")\\n            if not self.editing_id and any(r[\\"task_template_id\\"] == key for r in self.loaded_rows):\\n                raise ValueError(\\"Template ID already exists.\\")\\n            candidate = [dict(r) for r in self.loaded_rows if r[\\"task_template_id\\"] != key] + [row]\\n            self._validate_rows(candidate)\\n        except (OSError, UnicodeError, csv.Error, ValueError) as error:\\n            self.app.log(f\\"Task Templates Apply blocked; draft retained: {error}\\")\\n            messagebox.showerror(\\"Task Templates\\", str(error), parent=self.app)\\n            return\\n        self.loaded_rows = candidate\\n        self.editing_id = key\\n        self.dirty = True\\n        self._render_draft()\\n        self.tree.selection_set(key)\\n        self.on_select()\\n        self._set_status(\\"Template applied to draft. UNSAVED CHANGES.\\")\\n\\n    def revert_source(self):\\n        if self.dirty and not messagebox.askyesno(\\"Revert Task Templates Draft?\\", \\"Discard applied Task Templates draft changes and reload source?\\", parent=self.app):\\n            return\\n        try:\\n            self.update(force=True)\\n        except (OSError, UnicodeError, csv.Error, ValueError) as error:\\n            self.app.log(f\\"Task Templates reload failed; draft retained: {error}\\")\\n            messagebox.showerror(\\"Task Templates\\", str(error), parent=self.app)\\n\\n    def open_backups(self):"], ["doda_content_gui.py", "from doda_task_templates_editor import install_task_templates_editor", "from doda_task_templates_editor import install_task_templates_editor\\nfrom doda_task_draft_policy import task_draft_dirty, allow_task_project_change, install_task_draft_close_guard"], ["doda_content_gui.py", "        install_network_editor(self)\\n", "        install_network_editor(self)\\n        install_task_draft_close_guard(self, messagebox)\\n"], ["doda_content_gui.py", "    def choose_project_root(self) -> None:\\n", "    def choose_project_root(self) -> None:\\n        if not allow_task_project_change(self, messagebox):\\n            return\\n"], ["doda_content_gui.py", "    def run_validation(self) -> None:\\n", "    def run_validation(self) -> None:\\n        if task_draft_dirty(self):\\n            self.log(\\"Task Templates note: applied drafts are not included; this action uses saved source. Save to Source first to include them.\\")\\n"], ["doda_content_gui.py", "    def run_export(self) -> None:\\n", "    def run_export(self) -> None:\\n        if task_draft_dirty(self):\\n            self.log(\\"Task Templates note: applied drafts are not included; this action uses saved source. Save to Source first to include them.\\")\\n"], ["tests/test_row_selection.py", "def test_task_save_and_remove_blocked_for_multiple_rows(self):", "def test_task_apply_and_remove_blocked_for_multiple_rows(self):"], ["tests/test_row_selection.py", "            tasks.TaskTemplatesEditor.save(obj)", "            tasks.TaskTemplatesEditor.apply_record(obj)"]], "new_files": {"doda_task_draft_policy.py": "\\"\\"\\"Task draft protections layered around the existing shared close handler.\\"\\"\\"\\ndef task_draft_dirty(app):\\n    editor = getattr(app, \\"task_templates_editor\\", None)\\n    return bool(editor is not None and getattr(editor, \\"dirty\\", False))\\n\\n\\ndef allow_task_project_change(app, dialogs):\\n    if task_draft_dirty(app):\\n        dialogs.showwarning(\\"Task Templates\\", \\"Save to Source or Revert Draft before switching projects. Your Task Templates draft is retained.\\", parent=app)\\n        return False\\n    return True\\n\\n\\ndef install_task_draft_close_guard(app, dialogs):\\n    if getattr(app, \\"_task_draft_close_guard_installed\\", False):\\n        return\\n    previous = getattr(app, \\"_network_close_handler\\", None)\\n    def on_close():\\n        if task_draft_dirty(app) and not dialogs.askyesno(\\n            \\"Unsaved Task Templates Draft\\", \\"Close and discard applied Task Templates draft changes?\\", parent=app\\n        ):\\n            return\\n        if previous is not None:\\n            previous()\\n        else:\\n            app.destroy()\\n    app._network_close_handler = on_close\\n    app.protocol(\\"WM_DELETE_WINDOW\\", on_close)\\n    app._task_draft_close_guard_installed = True\\n", "tests/test_task_template_drafts.py": "import copy\\nimport csv\\nimport inspect\\nimport tempfile\\nimport unittest\\nfrom pathlib import Path\\nfrom types import SimpleNamespace as NS\\nfrom unittest.mock import Mock, patch\\n\\nimport doda_task_templates_editor as tasks\\nimport doda_task_draft_policy as policy\\nimport doda_content_gui as gui\\n\\n\\nclass Variable:\\n    def __init__(self, value=\\"\\"):\\n        self.value=value\\n    def set(self, value):\\n        self.value=value\\n    def get(self):\\n        return self.value\\n\\n\\nclass TaskTemplateDraftTests(unittest.TestCase):\\n    def setUp(self):\\n        self.temp=tempfile.TemporaryDirectory(prefix=\\"doda-task-draft-test-\\")\\n        self.addCleanup(self.temp.cleanup)\\n        self.root=Path(self.temp.name)\\n        self.path=self.root / \\"task_templates.csv\\"\\n        self.row={field:\\"\\" for field in tasks.FIELDS}\\n        self.row.update(task_template_id=\\"A\\",display_name=\\"One\\",description=\\"Description\\",priority=\\"NORMAL\\",target_type=\\"TERRITORY\\",loop_task=\\"FALSE\\",reward_mode=\\"CONTINUOUS\\",payout_count=\\"0\\",sort_order=\\"1\\",active=\\"FALSE\\")\\n        self.write_source([self.row])\\n        self.editor=tasks.TaskTemplatesEditor.__new__(tasks.TaskTemplatesEditor)\\n        e=self.editor\\n        e.app=NS(log=Mock(),refresh_all=Mock())\\n        e.status=Variable()\\n        e.tree=Mock()\\n        e.tree.selection.return_value=(\\"A\\",)\\n        e.loaded_rows=[dict(self.row)]\\n        e.editing_id=\\"A\\"\\n        e.dirty=False\\n        e.loaded_path=self.path.resolve()\\n        e.snapshot_hash=e.digest(self.path)\\n        e.source_path=lambda:self.path\\n        e.backup_directory=lambda:self.root / \\"backups\\"\\n        e.record=Mock(return_value={**self.row,\\"display_name\\":\\"Changed\\"})\\n        e._render_draft=Mock()\\n        e.on_select=Mock()\\n        e.new=Mock()\\n        e._validate_rows=Mock()\\n        e.candidate_valid=Mock(return_value=(True,\\"PASS\\"))\\n        e.choices=Mock(return_value=[])\\n        e.widgets={field:Mock() for field in tasks.FIELDS}\\n\\n    def write_source(self, rows):\\n        with self.path.open(\\"w\\",encoding=\\"utf-8\\",newline=\\"\\") as handle:\\n            writer=csv.DictWriter(handle,fieldnames=tasks.FIELDS)\\n            writer.writeheader()\\n            writer.writerows(rows)\\n\\n    def test_apply_updates_only_draft(self):\\n        before=self.path.read_bytes()\\n        self.editor.commit=Mock()\\n        self.editor.apply_record()\\n        self.assertEqual(self.path.read_bytes(),before)\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"Changed\\")\\n        self.assertTrue(self.editor.dirty)\\n        self.editor.commit.assert_not_called()\\n\\n    def test_apply_validation_failure_is_atomic(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor._validate_rows.side_effect=ValueError(\\"invalid candidate\\")\\n        with patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.apply_record()\\n        self.assertEqual(self.editor.loaded_rows,before)\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_apply_identity_change_blocked(self):\\n        self.editor.record.return_value={**self.row,\\"task_template_id\\":\\"B\\"}\\n        with patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.apply_record()\\n        self.assertEqual(self.editor.loaded_rows,[self.row])\\n        self.editor._validate_rows.assert_not_called()\\n\\n    def test_new_duplicate_id_blocked(self):\\n        self.editor.editing_id=None\\n        with patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.apply_record()\\n        self.assertFalse(self.editor.dirty)\\n        self.editor._validate_rows.assert_not_called()\\n\\n    def test_new_unique_row_is_draft_only(self):\\n        self.editor.editing_id=None\\n        self.editor.record.return_value={**self.row,\\"task_template_id\\":\\"B\\",\\"sort_order\\":\\"2\\"}\\n        before=self.path.read_bytes()\\n        self.editor.apply_record()\\n        self.assertEqual(len(self.editor.loaded_rows),2)\\n        self.assertEqual(self.path.read_bytes(),before)\\n\\n    def test_multi_apply_stays_blocked_in_v125a(self):\\n        self.editor.tree.selection.return_value=(\\"A\\",\\"B\\")\\n        with patch.object(tasks.messagebox,\\"showwarning\\"):\\n            self.editor.apply_record()\\n        self.editor.record.assert_not_called()\\n\\n    def test_delete_is_draft_only(self):\\n        before=self.path.read_bytes()\\n        self.editor.commit=Mock()\\n        with patch.object(tasks.messagebox,\\"askyesno\\",return_value=True):\\n            self.editor.remove()\\n        self.assertEqual(self.editor.loaded_rows,[])\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(self.path.read_bytes(),before)\\n        self.editor.commit.assert_not_called()\\n\\n    def test_delete_validation_failure_preserves_draft(self):\\n        self.editor._validate_rows.side_effect=ValueError(\\"referenced task\\")\\n        with patch.object(tasks.messagebox,\\"askyesno\\",return_value=True), patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.remove()\\n        self.assertEqual(self.editor.loaded_rows,[self.row])\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_delete_cancel_changes_nothing(self):\\n        with patch.object(tasks.messagebox,\\"askyesno\\",return_value=False):\\n            self.editor.remove()\\n        self.assertEqual(self.editor.loaded_rows,[self.row])\\n        self.editor._validate_rows.assert_not_called()\\n\\n    def test_refresh_keeps_dirty_draft_and_hash(self):\\n        self.editor.dirty=True\\n        self.editor.loaded_rows[0][\\"display_name\\"]=\\"Draft\\"\\n        saved_hash=self.editor.snapshot_hash\\n        self.write_source([{**self.row,\\"display_name\\":\\"External\\"}])\\n        self.editor.update()\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"Draft\\")\\n        self.assertEqual(self.editor.snapshot_hash,saved_hash)\\n        self.assertTrue(self.editor.dirty)\\n        self.editor._render_draft.assert_not_called()\\n\\n    def test_clean_refresh_loads_source(self):\\n        self.write_source([{**self.row,\\"display_name\\":\\"External\\"}])\\n        self.editor.update()\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"External\\")\\n        self.assertFalse(self.editor.dirty)\\n        self.assertEqual(self.editor.snapshot_hash,self.editor.digest(self.path))\\n\\n    def test_dirty_cross_project_refresh_blocked(self):\\n        self.editor.dirty=True\\n        self.editor.loaded_path=(self.root / \\"another_project.csv\\").resolve()\\n        with self.assertRaises(ValueError):\\n            self.editor.update()\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(self.editor.loaded_rows,[self.row])\\n\\n    def test_revert_cancel_keeps_dirty_draft(self):\\n        self.editor.dirty=True\\n        self.editor.update=Mock()\\n        with patch.object(tasks.messagebox,\\"askyesno\\",return_value=False):\\n            self.editor.revert_source()\\n        self.editor.update.assert_not_called()\\n        self.assertTrue(self.editor.dirty)\\n\\n    def test_revert_reloads_source_without_writing(self):\\n        self.editor.dirty=True\\n        self.editor.loaded_rows[0][\\"display_name\\"]=\\"Draft\\"\\n        before=self.path.read_bytes()\\n        with patch.object(tasks.messagebox,\\"askyesno\\",return_value=True):\\n            self.editor.revert_source()\\n        self.assertFalse(self.editor.dirty)\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"One\\")\\n        self.assertEqual(self.path.read_bytes(),before)\\n\\n    def test_revert_read_error_keeps_dirty_draft(self):\\n        self.editor.dirty=True\\n        self.path.unlink()\\n        with patch.object(tasks.messagebox,\\"askyesno\\",return_value=True),patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.revert_source()\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(self.editor.loaded_rows,[self.row])\\n\\n    def test_save_without_apply_does_not_commit_form(self):\\n        self.editor.commit=Mock()\\n        self.editor.save()\\n        self.editor.commit.assert_not_called()\\n        self.editor.record.assert_not_called()\\n\\n    def test_save_uses_draft_even_with_multiple_selection(self):\\n        self.editor.dirty=True\\n        self.editor.tree.selection.return_value=(\\"A\\",\\"B\\")\\n        self.editor.commit=Mock()\\n        self.editor.save()\\n        self.editor.commit.assert_called_once_with(self.editor.loaded_rows)\\n        self.editor.record.assert_not_called()\\n\\n    def test_successful_source_save_creates_backup(self):\\n        original=self.path.read_bytes()\\n        self.editor.loaded_rows[0][\\"display_name\\"]=\\"Draft\\"\\n        self.editor.dirty=True\\n        with patch.object(tasks.messagebox,\\"showinfo\\"):\\n            self.editor.save()\\n        self.assertFalse(self.editor.dirty)\\n        self.assertEqual(self.editor.snapshot_hash,self.editor.digest(self.path))\\n        backups=list((self.root / \\"backups\\").glob(\\"*.csv\\"))\\n        self.assertEqual(len(backups),1)\\n        self.assertEqual(backups[0].read_bytes(),original)\\n        with self.path.open(newline=\\"\\") as handle:\\n            self.assertEqual(next(csv.DictReader(handle))[\\"display_name\\"],\\"Draft\\")\\n        self.assertEqual(list(self.root.glob(\\".tasks-*.tmp.csv\\")),[])\\n\\n    def test_pre_validation_hash_conflict_preserves_source(self):\\n        self.editor.dirty=True\\n        self.write_source([{**self.row,\\"display_name\\":\\"External\\"}])\\n        external=self.path.read_bytes()\\n        with patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.save()\\n        self.assertEqual(self.path.read_bytes(),external)\\n        self.assertTrue(self.editor.dirty)\\n        self.editor.candidate_valid.assert_not_called()\\n\\n    def test_validation_failure_keeps_dirty_draft(self):\\n        self.editor.dirty=True\\n        self.editor.candidate_valid.return_value=(False,\\"FAIL\\")\\n        before=self.path.read_bytes()\\n        with patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.save()\\n        self.assertEqual(self.path.read_bytes(),before)\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(list(self.root.glob(\\".tasks-*.tmp.csv\\")),[])\\n\\n    def test_source_changed_during_validation_is_not_overwritten(self):\\n        self.editor.dirty=True\\n        def validation(_candidate):\\n            self.write_source([{**self.row,\\"display_name\\":\\"External\\"}])\\n            return True,\\"PASS\\"\\n        self.editor.candidate_valid.side_effect=validation\\n        with patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.save()\\n        self.assertTrue(self.editor.dirty)\\n        with self.path.open(newline=\\"\\") as handle:\\n            self.assertEqual(next(csv.DictReader(handle))[\\"display_name\\"],\\"External\\")\\n        self.assertFalse((self.root / \\"backups\\").exists())\\n\\n    def test_source_changed_during_backup_is_not_overwritten(self):\\n        self.editor.dirty=True\\n        real_copy=tasks.shutil.copy2\\n        def backup(source,destination):\\n            result=real_copy(source,destination)\\n            self.write_source([{**self.row,\\"display_name\\":\\"External\\"}])\\n            return result\\n        with patch.object(tasks.shutil,\\"copy2\\",side_effect=backup), patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.save()\\n        self.assertTrue(self.editor.dirty)\\n        with self.path.open(newline=\\"\\") as handle:\\n            self.assertEqual(next(csv.DictReader(handle))[\\"display_name\\"],\\"External\\")\\n\\n    def test_backup_error_retains_draft(self):\\n        self.editor.dirty=True\\n        before=self.path.read_bytes()\\n        with patch.object(tasks.shutil,\\"copy2\\",side_effect=OSError(\\"backup failed\\")),patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.save()\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(self.path.read_bytes(),before)\\n        self.assertEqual(list(self.root.glob(\\".tasks-*.tmp.csv\\")),[])\\n\\n    def test_write_error_retains_draft(self):\\n        self.editor.dirty=True\\n        before=self.path.read_bytes()\\n        with patch.object(tasks.os,\\"replace\\",side_effect=OSError(\\"write failed\\")),patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.save()\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(self.path.read_bytes(),before)\\n        self.assertEqual(list(self.root.glob(\\".tasks-*.tmp.csv\\")),[])\\n\\n    def test_save_read_error_retains_draft(self):\\n        self.editor.dirty=True\\n        with patch.object(self.editor,\\"digest\\",side_effect=OSError(\\"read failed\\")),patch.object(tasks.messagebox,\\"showerror\\"):\\n            self.editor.save()\\n        self.assertTrue(self.editor.dirty)\\n        self.editor.candidate_valid.assert_not_called()\\n\\n    def test_candidate_validation_uses_temp_file_only(self):\\n        before=self.path.read_bytes()\\n        paths=[]\\n        def validation(path):\\n            paths.append(path)\\n            self.assertTrue(path.is_file())\\n            self.assertNotEqual(path,self.path)\\n            return True,\\"PASS\\"\\n        self.editor.candidate_valid.side_effect=validation\\n        tasks.TaskTemplatesEditor._validate_rows(self.editor,[self.row])\\n        self.assertEqual(self.path.read_bytes(),before)\\n        self.assertFalse(paths[0].exists())\\n\\n\\nclass TaskDraftPolicyTests(unittest.TestCase):\\n    def setUp(self):\\n        self.previous=Mock()\\n        self.app=NS(task_templates_editor=NS(dirty=True),_network_close_handler=self.previous,protocol=Mock(),destroy=Mock())\\n        self.dialogs=Mock()\\n\\n    def test_close_cancel_preserves_task_draft(self):\\n        self.dialogs.askyesno.return_value=False\\n        policy.install_task_draft_close_guard(self.app,self.dialogs)\\n        self.app._network_close_handler()\\n        self.previous.assert_not_called()\\n        self.assertTrue(self.app.task_templates_editor.dirty)\\n\\n    def test_close_confirm_delegates_to_shared_guard(self):\\n        self.dialogs.askyesno.return_value=True\\n        policy.install_task_draft_close_guard(self.app,self.dialogs)\\n        self.app._network_close_handler()\\n        self.previous.assert_called_once()\\n        self.app.destroy.assert_not_called()\\n\\n    def test_clean_task_close_does_not_add_prompt(self):\\n        self.app.task_templates_editor.dirty=False\\n        policy.install_task_draft_close_guard(self.app,self.dialogs)\\n        self.app._network_close_handler()\\n        self.dialogs.askyesno.assert_not_called()\\n        self.previous.assert_called_once()\\n\\n    def test_dirty_task_blocks_project_change(self):\\n        self.assertFalse(policy.allow_task_project_change(self.app,self.dialogs))\\n        self.dialogs.showwarning.assert_called_once()\\n        self.assertTrue(self.app.task_templates_editor.dirty)\\n\\n    def test_clean_task_allows_project_change(self):\\n        self.app.task_templates_editor.dirty=False\\n        self.assertTrue(policy.allow_task_project_change(self.app,self.dialogs))\\n        self.dialogs.showwarning.assert_not_called()\\n\\n    def test_close_guard_installation_is_idempotent(self):\\n        policy.install_task_draft_close_guard(self.app,self.dialogs)\\n        first=self.app._network_close_handler\\n        policy.install_task_draft_close_guard(self.app,self.dialogs)\\n        self.assertIs(self.app._network_close_handler,first)\\n        self.app.protocol.assert_called_once()\\n\\n    def test_project_change_guard_runs_before_folder_picker(self):\\n        with patch.object(gui,\\"allow_task_project_change\\",return_value=False),patch.object(gui.filedialog,\\"askdirectory\\") as picker:\\n            gui.ContentWorkbenchApp.choose_project_root(self.app)\\n        picker.assert_not_called()\\n\\n    def test_file_exit_uses_wrapped_close_handler(self):\\n        self.dialogs.askyesno.return_value=False\\n        policy.install_task_draft_close_guard(self.app,self.dialogs)\\n        gui.ContentWorkbenchApp.request_close(self.app)\\n        self.previous.assert_not_called()\\n"}}')
root=Path(sys.argv[1]).resolve()
module=root / "tools" / "doda_content_workbench"
source=root / "data_authoring" / "source"
if not module.is_dir() or not source.is_dir():
    raise SystemExit("Project directories missing; nothing installed.")

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None

def guard():
    errors=[]
    for name,expected in payload["guards"].items():
        actual=sha(module / name)
        if actual != expected:
            errors.append(f"{name}: expected {expected}, actual {actual}")
    for name in payload["new_files"]:
        if (module / name).exists():
            errors.append(name + ": target already exists")
    if errors:
        raise RuntimeError("GUARD FAILED. Inspect current local files; do not bypass.\n" + "\n".join(errors))

try:
    guard()
except Exception as error:
    print(error)
    raise SystemExit(1)
csv_bytes={p.relative_to(source).as_posix():p.read_bytes() for p in source.rglob("*.csv")}
if not csv_bytes:
    raise SystemExit("No source CSVs found; nothing installed.")

def csv_guard():
    now={p.relative_to(source).as_posix():p.read_bytes() for p in source.rglob("*.csv")}
    if now != csv_bytes:
        changed=sorted(name for name in set(now) | set(csv_bytes) if now.get(name) != csv_bytes.get(name))
        raise RuntimeError("Source CSV changed during installation: " + ", ".join(changed))

stamp=datetime.now().strftime("%Y%m%d_%H%M%S") + "_" + uuid4().hex[:8]
backup=module / "backups" / ("v125a_task_drafts_" + stamp)
backup.mkdir(parents=True)
originals={name:(module / name).read_bytes() for name in sorted(set(p[0] for p in payload["patches"]))}
for name,data in originals.items():
    dest=backup / "modified_files" / name
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_bytes(data)
for name,data in csv_bytes.items():
    dest=backup / "source_csv_snapshot" / name
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_bytes(data)
(backup / "source_manifest.json").write_text(json.dumps({name:hashlib.sha256(data).hexdigest() for name,data in csv_bytes.items()},indent=2),encoding="utf-8")
print("Backup and logs:",backup,flush=True)

def suite(label,minimum):
    env=dict(os.environ)
    env["PYTHONPATH"]=str(module) + os.pathsep + env.get("PYTHONPATH","")
    env["PYTHONDONTWRITEBYTECODE"]="1"
    done=subprocess.run([sys.executable,"-m","unittest","discover","-s",str(module / "tests"),"-p","test_*.py"],
        cwd=root,env=env,text=True,encoding="utf-8",errors="replace",stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=900)
    (backup / (label + ".log")).write_text(done.stdout,encoding="utf-8")
    print(done.stdout,flush=True)
    counts=re.findall(r"Ran (\d+) tests? in",done.stdout)
    count=int(counts[-1]) if counts else 0
    if done.returncode != 0 or count < minimum:
        raise RuntimeError(f"{label} failed: exit {done.returncode}, tests {count}, required >= {minimum}.")
    csv_guard()
    return count

written={}
try:
    baseline=suite("baseline",774)
    guard()
    candidates={}
    for name,data in originals.items():
        text=data.decode("utf-8-sig").replace("\r\n","\n")
        for target,old,new in payload["patches"]:
            if name != target:
                continue
            if text.count(old) != 1:
                raise RuntimeError("Content guard failed: " + name + ". Inspect current file.")
            text=text.replace(old,new)
        ast.parse(text)
        newline="\r\n" if b"\r\n" in data else "\n"
        encoded=text.replace("\n",newline).encode("utf-8")
        if data.startswith(b"\xef\xbb\xbf"):
            encoded=b"\xef\xbb\xbf" + encoded
        candidates[name]=encoded
    for name,text in payload["new_files"].items():
        ast.parse(text)
        candidates[name]=text.encode("utf-8")
    guard()
    csv_guard()
    for name,data in candidates.items():
        path=module / name
        tmp=path.with_name("." + path.name + "." + uuid4().hex + ".tmp")
        try:
            tmp.write_bytes(data)
            if name in originals and path.read_bytes() != originals[name]:
                raise RuntimeError("File changed before write: " + name)
            if name not in originals and path.exists():
                raise RuntimeError("New target appeared before write: " + name)
            os.replace(tmp,path)
            written[name]=data
        finally:
            tmp.unlink(missing_ok=True)
    after=suite("post_install",baseline + 34)
    csv_guard()
    for name,data in written.items():
        if (module / name).read_bytes() != data:
            raise RuntimeError("Patched file changed during tests: " + name)
    for name,expected in payload["guards"].items():
        if name not in written and sha(module / name) != expected:
            raise RuntimeError("Unmodified guarded file changed: " + name)
    hashes={name:sha(module / name) for name in written}
    (backup / "installed_hashes.json").write_text(json.dumps(hashes,indent=2),encoding="utf-8")
    print(f"V125A INSTALLED: baseline {baseline}, post-install {after}; {len(csv_bytes)} source CSVs unchanged.")
    print("Task Templates: draft Apply/Delete, separate Save to Source, refresh/close/project guards enabled.")
    print("Shared editors unchanged. Multi-row Task Template Apply remains blocked until v125b. Manual GUI check required.")
    print(json.dumps(hashes,indent=2))
except BaseException as error:
    failures=[]
    for name,data in reversed(list(written.items())):
        path=module / name
        try:
            if not path.is_file() or path.read_bytes() != data:
                raise RuntimeError("Current file differs from patch output; refusing to overwrite external edits.")
            if name in originals:
                tmp=path.with_name("." + path.name + ".rollback." + uuid4().hex)
                try:
                    tmp.write_bytes(originals[name])
                    os.replace(tmp,path)
                finally:
                    tmp.unlink(missing_ok=True)
                if path.read_bytes() != originals[name]:
                    raise RuntimeError("Rollback verification failed.")
            else:
                path.unlink()
        except Exception as rollback_error:
            failures.append(name + ": " + str(rollback_error))
    print("INSTALLATION STOPPED:",str(error))
    print("Patched files rolled back." if not failures else "ROLLBACK NEEDS INSPECTION:\n" + "\n".join(failures))
    try:
        csv_guard()
        print("Source CSVs unchanged.")
    except Exception as source_error:
        print(source_error)
        print("Source snapshot retained in backup. No CSV is overwritten automatically; inspect before restoration.")
    print("Backup and logs:",backup)
    raise SystemExit(1)

'@
$temporary = Join-Path $env:TEMP ('doda_v125a_' + [guid]::NewGuid().ToString('N') + '.py')
try {
    [IO.File]::WriteAllText($temporary, $code, (New-Object System.Text.UTF8Encoding($false)))
    & $python $temporary $Root
    if ($LASTEXITCODE -ne 0) { throw "v125a stopped with exit code $LASTEXITCODE. Inspect the reported log/backup before retrying." }
} finally {
    Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue
}
